package com.novacommerce.order.api; import com.novacommerce.order.application.*; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/orders")public class OrderController{private final OrderQueryService orders;private final OrderCancellationService cancellation;public OrderController(OrderQueryService o,OrderCancellationService c){orders=o;cancellation=c;}@GetMapping OrderDtos.OrderPage list(@AuthenticationPrincipal Jwt j,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var result=orders.list(CartController.owner(j),page,size);return new OrderDtos.OrderPage(result.getContent().stream().map(OrderDtos.OrderResponse::from).toList(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}@GetMapping("/{id}")OrderDtos.OrderResponse get(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){return OrderDtos.OrderResponse.from(orders.get(CartController.owner(j),id));}@PostMapping("/{id}/cancel")OrderDtos.OrderResponse cancel(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){boolean admin=j.getClaimAsStringList("roles")!=null&&j.getClaimAsStringList("roles").contains("ADMIN");return OrderDtos.OrderResponse.from(cancellation.cancel(CartController.owner(j),id,admin,j.getTokenValue()));}}
